\newcommand{\@paperType}{\tt$\backslash$\string paperType}

\newcommand{\cityName}[1]{\renewcommand{\@cityName}{#1}}
\newcommand{\@cityName}{\tt$\backslash$\string cityName}

\newcommand{\university}[1]{\renewcommand{\@university}{#1}}
\newcommand{\@university}{\tt$\backslash$\string university}
\newcommand{\faculty}[1]{\newcommand{\@faculty}{#1}}
%\newcommand{\@department}{\tt$\backslash$\string department}

\newcommand{\department}[1]{\renewcommand{\@department}{#1}}
\newcommand{\@department}{\tt$\backslash$\string department}

\newcommand{\sisiId}[1]{\newcommand{\@sisiId}{#1}}

%
% Redefine maketitle
\newlength{\fiveblanklines}\setlength{\fiveblanklines}{0.7 in}
\newlength{\tenblanklines}\setlength{\tenblanklines}{1.5 in}

\newcommand\makefrontpage{
  \enlargethispage{0.5in} %make extra room where page number would go
  \thispagestyle{empty}
  \noindent
  \begin{minipage}[t][\textheight][t]{\linewidth}
  \begin{center}
	\textbf{\@university} \\
    \textbf{\@faculty}\\ 
    \textbf{\@department}

  \end{center}
  \vspace{\tenblanklines}
  \begin{center}
  	\large{\@author}
    \parbox{0.92\linewidth}{\centering
    \begin{LARGE}
			extbf{\@title}
	\end{LARGE}\par}
	\\ \ \\
	\parbox{0.92\linewidth}{\centering
	\begin{large}
			extbf{(\@titleEng)}
	\end{large}\par}
	\\ \ \\
	\begin{Large}
		\textbf{(\@titleEng)}
	\end{Large}
	 \\ \ \\	

    \@programeName

    \@degreeName

  \end{center}
  \vspace{\tenblanklines}
  \vfill
   \begin{center}
    \parbox{0.92\linewidth}{\centering
    \begin{Large}
			extbf{\@title}
	\end{Large}\par}
	\\ \ \\
	\parbox{0.92\linewidth}{\centering
	\begin{large}
			extbf{(\@titleEng)}
	\end{large}\par}

\clearpage
}

\renewcommand\maketitle{
  \enlargethispage{0.5in} %make extra room where page number would go
  \setcounter{page}{0}
  \thispagestyle{empty}
\begin{minipage}[t][\textheight][t]{\linewidth}
  \begin{center}

	\textbf{\@university} \\
    \textbf{\@faculty}\\ 
    \textbf{\@department}

  \end{center}
  \vspace{\tenblanklines}

  \vspace{\fiveblanklines}
  \begin{center}
    \singlespace
    \begin{Large}
		\textbf{\@title}
	\end{Large}
	\\ \ \\
	\begin{Large}
		\textbf{(\@titleEng)}
	\end{Large}
	 \\ \ \\	
     \@programeName

	\@degreeName
  \end{center}
  \vspace{\tenblanklines}

\noindent
\begin{tabularx}{\linewidth}{@{}p{3cm}p{4.5cm}X@{}}
  Удирдагч: & \underline{\hspace{4cm}} & \@supervisor \\[0.8cm]
  % Хамтран удирдагч: & \underline{\hspace{4cm}} & \@cosupervisor \\
  Гүйцэтгэсэн: & \underline{\hspace{4cm}} & \@authorShort\ (\@sisiId)
\end{tabularx}

   \vfill
   \begin{center}
   \doublespace

   \@cityName \\
	 \@gradyear
   \end{center} 

\end{minipage}
\clearpage
}

%
% redefine abstract environment
%
\renewenvironment{abstract}{
  %\setcounter{page}{1}
  \addcontentsline{toc}{part}{УДИРТГАЛ}
  \begin{center}
    \doublespace
    \begin{large}
    \textbf{УДИРТГАЛ}
    \end{large}
  \end{center}
} {
  \clearpage
}

%
% make acknowledgements environment
%
\newenvironment{acknowledgements}{
  \begin{center}
    \doublespace
    ТАЛАРХАЛ
  \end{center}
} {
  \clearpage
}

%
% define \dedicationpage
